const r = $input.item.json;
const data = r.data || r;
const upcoming = data.upcoming_fpds || data.fpds_within_14_days || data.upcoming || [];
const synced = data.anchors_synced || data.events_updated || 0;
const hasUrgent = upcoming.length > 0;

const ts = new Date().toLocaleString('en-US', {timeZone: 'America/Denver', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'});

let message = `*D2M Booking Anchors — ${ts}*\n\n${synced} anchor(s) synced to calendar.`;

if (hasUrgent) {
  const lines = upcoming.map(fpd => {
    const days = fpd.days_remaining !== undefined ? ` — ${fpd.days_remaining}d remaining` : '';
    const client = fpd.client || fpd.client_name || '';
    const clientStr = client ? ` (${client})` : '';
    return `• ${fpd.type || 'FPD'}: ${fpd.date || fpd.due_date}${clientStr}${days}`;
  });
  message += `\n\n*Upcoming Deadlines (≤14 days):*\n${lines.join('\n')}`;
}

return [{ json: { hasUrgent, message, upcomingCount: upcoming.length, synced } }];
